typedef struct { char pad0[0x10]; float x; float y; } L18Pos;

/* Returns the class 0x247 moby in list idx whose bearing from a differs most from b's, or 0. */
void *find_class_247_moby_with_largest_xy_angle_in_list(float *a, float *b, int idx) {
    short *p = (short *)veldin2_moby_groups[idx];
    char *best = 0;
    float bestd = 0.0f;
    if (p == 0) return 0;
    while (1) {
        int off = (*p & 0x7FFF) << 8;
        if (*(short *)(off + (int)veldin2_moby_table_base.base + 0xA6) == 0x247) {
            float ang = fast_atan2(a[0] - b[0], a[1] - b[1]);
            L18Pos *m = (L18Pos *)(off + (int)veldin2_moby_table_base.base);
            float d = FastDiffRots(ang, fast_atan2(a[0] - m->x, a[1] - m->y));
            if (bestd < d) {
                bestd = d;
                best = veldin2_moby_table_m + off;
            }
        }
        if (*p++ < 0) return best;
    }
}

/* Of the mobys of class 0x247 in list idx, the one nearest to pos (within
   255 units), or 0. The second spelling of the table base keeps the
   address out of the loop's $gp-relative reload in the bc1f delay slot. */
char *find_nearest_class_247_moby_in_list(void *pos, int idx) {
    short *p = (short *)veldin2_moby_groups[idx];
    char *best = 0;
    float bestd = 255.0f;
    if (p == 0) return 0;
    while (1) {
        int off = (*p & 0x7FFF) << 8;
        char *m = (char *)(off + (int)veldin2_moby_table_m);
        if (*(short *)(m + 0xA6) == 0x247) {
            float d = FastVecDist(pos, m + 0x10);
            if (d < bestd) {
                bestd = d;
                best = veldin2_moby_table_m + off;
            }
        }
        if (*p++ < 0) return best;
    }
}

// Sets the data fields 0x30 and 0x24 of each listed moby whose class is 0x247.
void set_class_247_list_data_fields(int idx) {
    short *p = (short *)veldin2_moby_groups[idx];
    if (p != 0) {
        char *base = veldin2_moby_table_m;
        do {
            int off = (*p & 0x7FFF) << 8;
            char *moby = (char *)off + (int)base;
            if (((Moby *)moby)->oclass == 0x247) {
                char *data = ((char *)((Moby *)moby)->pvars);
                *(int *)(data + 0x30) = 1;
                *(float *)(data + 0x24) = 1.5f;
            }
        } while (*p++ >= 0);
    }
}
