/* Damage ring for the class 0x270 moby. */
void process_expanding_ring_collisions(char *moby) {
    char hit[0x30];
    float v[4];
    float a[4];
    float b[4];
    struct RingVars *d = (struct RingVars *)((Moby *)moby)->pvars;
    float p, q, step;
    int i;

    FastVecSub(v,&((struct Hero *)((char *)&hero_globals_base + 0xE1D))->motion.pos, moby + 0x10);
    v[2] = 0.0f;
    vec_scale_to_length(v, v, g_frame_time * 4.0f);
    v[2] = g_frame_time * 4.0f;
    InitDirectionalHitQuery(hit, (int)moby, 0x10001, v, 3.0f);
    step = 1.0f / IntToFloat(0x40) * 6.28318f;
    p = -3.14159f;
    q = FastAddRots(p, step);
    for (i = 0x3F; i >= 0; i--) {
        a[0] = FastCos(p) * d->radius;
        a[1] = FastSin(p) * d->radius;
        a[2] = 0.0f;
        b[0] = FastCos(q) * d->radius;
        b[1] = FastSin(q) * d->radius;
        b[2] = 0.0f;
        FastVecAdd(a, a, moby + 0x10);
        a[2] += 0.5f;
        FastVecAdd(b, b, moby + 0x10);
        b[2] += 0.5f;
        coll_line(a, b, 1, d->owner, hit);
        if (d->radius < 3.0f) {
            spawn_expanding_ring_segment_particles(moby, a, b);
        }
        p = FastAddRots(p, step);
        q = FastAddRots(q, step);
    }
}
