/* UpdateMoby_628 */
void update_class_274_ring_effect(char *moby) {
    char buf[0x30];
    float v[4];
    float *d = ((float *)((Moby *)moby)->pvars);
    char *tgt;
    char *pos;
    int flag;

    if (fast_dec_timer((int *)(d + 2))) {
        DeleteMoby(moby);
        return;
    }
    pos = moby + 0x10;
    tgt =&((struct Hero *)((char *)&hero_globals_base + 0xE1D))->motion.pos;
    if (vec_distance_xy(pos, tgt) < d[0] + 0.5f) {
        FastVecSub(v, tgt, pos);
        v[2] = 0.0f;
        vec_scale_to_length(v, v, g_frame_time * 4.0f);
        v[2] = g_frame_time * 4.0f;
        InitDirectionalHitQuery(buf, (int)moby, 0x10001, v, 1.0f);
        record_moby_hit(*(int *)(tgt + 0x2000), buf);
    }
    flag = veldin2_frame_count & 4;
    d[1] = d[1] + *(float *)&ring_effect_color_scroll_speed * g_frame_time;
    if (flag == 0) {
        MobySphereHitDirectional(*(int *)(d + 3), d[0], pos, 0x10000, 1.0f, 1.0f, 0, 1, 0);
    }
    AddDrawCallback(draw_class_274_ring_effect, moby);
}
